function gcallTick() {
  const el = document.getElementById("gcall-timer");
  if (el) el.textContent = formatClock(Date.now() - GC.startedAt);
}

// ---------- UI ----------
function gcallStopRing() { clearTimeout(GC.ringTimer); GC.ringTimer = null; try { stopRingtone(); } catch (e) {} }

